replaceOnce(
  'internal/server/server.go',
  'threads preserve initiator participant identity',
  [
    '	for i, participant := range participants {',
    '		storedID, agentClassID, err := s.finalParticipantID(ctx, participant.ID, typesByID[participant.ID])',
    '		if err != nil {',
    '			return nil, nil, err',
    '		}',
    '		if _, ok := seen[storedID]; ok {',
    '			if hasInitiator && storedID == initiatorID {',
    '				continue',
    '			}',
    '			return nil, nil, status.Errorf(codes.InvalidArgument, "participants[%d]: duplicate participant", i)',
    '		}',
    '		seen[storedID] = struct{}{}',
    '		finalParticipants = append(finalParticipants, store.ParticipantInput{ID: storedID, Passive: false})',
    '		if agentClassID != uuid.Nil {',
    '			agentClassIDs = append(agentClassIDs, agentClassID)',
    '		}',
    '	}',
  ].join('\n'),
  [
    '	for i, participant := range participants {',
    '		storedID := participant.ID',
    '		agentClassID := uuid.Nil',
    '		preserveInitiator := hasInitiator && participant.ID == initiatorID && isAgentInstanceIdentity(ctx)',
    '		if !preserveInitiator {',
    '			var err error',
    '			storedID, agentClassID, err = s.finalParticipantID(ctx, participant.ID, typesByID[participant.ID])',
    '			if err != nil {',
    '				return nil, nil, err',
    '			}',
    '		}',
    '		if _, ok := seen[storedID]; ok {',
    '			if hasInitiator && storedID == initiatorID {',
    '				continue',
    '			}',
    '			return nil, nil, status.Errorf(codes.InvalidArgument, "participants[%d]: duplicate participant", i)',
    '		}',
    '		seen[storedID] = struct{}{}',
    '		finalParticipants = append(finalParticipants, store.ParticipantInput{ID: storedID, Passive: false})',
    '		if agentClassID != uuid.Nil {',
    '			agentClassIDs = append(agentClassIDs, agentClassID)',
    '		}',
    '	}',
  ].join('\n'),
);

const testPath = 'internal/server/server_test.go';
let testText = fs.readFileSync(testPath, 'utf8');
if (!testText.includes('func TestCreateThreadPreservesAgentInstanceInitiatorParticipant(')) {
  const marker = 'func TestCreateThreadStoresAgentInstanceForAgentClassParticipant(t *testing.T) {';
  if (!testText.includes(marker)) {
    throw new Error('threads create agent instance marker not found');
  }
  const addition = [
    'func TestCreateThreadPreservesAgentInstanceInitiatorParticipant(t *testing.T) {',
    '\tthreadID := uuid.New()',
    '\torganizationID := uuid.New()',
    '\tagentInstanceID := uuid.New()',
    '\tagentID := uuid.New()',
    '\totherParticipantID := uuid.New()',
    '\tnow := time.Now().UTC()',
    '',
    '\tstoreStub := &stubThreadStore{',
    '\t\tt: t,',
    '\t\tcreateThreadFn: func(ctx context.Context, orgID uuid.UUID, participants []store.ParticipantInput) (store.Thread, error) {',
    '\t\t\tif orgID != organizationID {',
    '\t\t\t\tt.Fatalf("expected organization %s, got %s", organizationID, orgID)',
    '\t\t\t}',
    '\t\t\tif len(participants) != 2 {',
    '\t\t\t\tt.Fatalf("expected 2 participants, got %d", len(participants))',
    '\t\t\t}',
    '\t\t\tif participants[0].ID != agentInstanceID {',
    '\t\t\t\tt.Fatalf("expected initiator instance %s, got %s", agentInstanceID, participants[0].ID)',
    '\t\t\t}',
    '\t\t\tif participants[1].ID != otherParticipantID {',
    '\t\t\t\tt.Fatalf("expected participant %s, got %s", otherParticipantID, participants[1].ID)',
    '\t\t\t}',
    '\t\t\treturn store.Thread{',
    '\t\t\t\tID:             threadID,',
    '\t\t\t\tOrganizationID: &organizationID,',
    '\t\t\t\tStatus:         store.ThreadStatusActive,',
    '\t\t\t\tCreatedAt:      now,',
    '\t\t\t\tUpdatedAt:      now,',
    '\t\t\t\tParticipants: []store.Participant{',
    '\t\t\t\t\t{ID: agentInstanceID, JoinedAt: now},',
    '\t\t\t\t\t{ID: otherParticipantID, JoinedAt: now},',
    '\t\t\t\t},',
    '\t\t\t}, nil',
    '\t\t},',
    '\t}',
    '\tidentityStub := &stubIdentityResolver{',
    '\t\tt: t,',
    '\t\ttypeBatchFn: func(ctx context.Context, req *identityv1.BatchGetIdentityTypesRequest, opts ...grpc.CallOption) (*identityv1.BatchGetIdentityTypesResponse, error) {',
    '\t\t\tentries := make([]*identityv1.IdentityTypeEntry, len(req.GetIdentityIds()))',
    '\t\t\tfor i, id := range req.GetIdentityIds() {',
    '\t\t\t\tidentityType := identityv1.IdentityType_IDENTITY_TYPE_USER',
    '\t\t\t\tif id == agentInstanceID.String() {',
    '\t\t\t\t\tidentityType = identityv1.IdentityType_IDENTITY_TYPE_AGENT',
    '\t\t\t\t}',
    '\t\t\t\tentries[i] = &identityv1.IdentityTypeEntry{IdentityId: id, IdentityType: identityType}',
    '\t\t\t}',
    '\t\t\treturn &identityv1.BatchGetIdentityTypesResponse{Entries: entries}, nil',
    '\t\t},',
    '\t}',
    '\tagentsStub := &stubAgentsService{',
    '\t\tt: t,',
    '\t\tgetInstanceFn: func(ctx context.Context, req *agentsv1.GetInstanceRequest, opts ...grpc.CallOption) (*agentsv1.GetInstanceResponse, error) {',
    '\t\t\tif req.GetId() != agentInstanceID.String() {',
    '\t\t\t\tt.Fatalf("expected instance id %s, got %s", agentInstanceID, req.GetId())',
    '\t\t\t}',
    '\t\t\treturn &agentsv1.GetInstanceResponse{Instance: &agentsv1.AgentInstance{Meta: &agentsv1.EntityMeta{Id: agentInstanceID.String()}, AgentId: agentID.String()}}, nil',
    '\t\t},',
    '\t\tgetAgentFn: func(ctx context.Context, req *agentsv1.GetAgentRequest, opts ...grpc.CallOption) (*agentsv1.GetAgentResponse, error) {',
    '\t\t\tif req.GetId() != agentID.String() {',
    '\t\t\t\tt.Fatalf("expected agent id %s, got %s", agentID, req.GetId())',
    '\t\t\t}',
    '\t\t\treturn &agentsv1.GetAgentResponse{Agent: &agentsv1.Agent{OrganizationId: organizationID.String()}}, nil',
    '\t\t},',
    '\t}',
    '\tauthStub := allowAuthStub(t)',
    '\tsrv := New(storeStub, nil, authStub, identityStub, agentsStub, nil)',
    '\tctx := metadata.NewIncomingContext(context.Background(), metadata.Pairs("x-identity-id", agentInstanceID.String(), "x-identity-type", agentInstanceIdentityType))',
    '\torgIDValue := organizationID.String()',
    '\t_, err := srv.CreateThread(ctx, &threadsv1.CreateThreadRequest{',
    '\t\tOrganizationId:  &orgIDValue,',
    '\t\tParticipantIds: []string{otherParticipantID.String()},',
    '\t})',
    '\tif err != nil {',
    '\t\tt.Fatalf("CreateThread returned error: %v", err)',
    '\t}',
    '}',
    '',
  ].join('\n');
  testText = testText.replace(marker, addition + marker);
}

